contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single test function driving getTokens with an ETH value amount
    function run(uint256 sendAmount) public payable {
        // ensure this contract has enough ETH to forward
        require(address(this).balance >= sendAmount);

        // read observable state before the call
        uint256 beforeBalance = c.balanceOf(address(this));
        uint256 beforeTotalDistributed = c.totalDistributed();
        bool beforeBlacklisted = c.blacklist(address(this));
        uint256 contractEthBefore = address(c).balance;

        // perform the call and capture whether it reverted
        bool reverted;
        try c.getTokens{value: sendAmount}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        // read observable state after the call
        uint256 afterBalance = c.balanceOf(address(this));
        uint256 afterTotalDistributed = c.totalDistributed();
        bool afterBlacklisted = c.blacklist(address(this));
        uint256 contractEthAfter = address(c).balance;

        // General rule:
        // If call succeeded (not reverted) then:
        //  - afterBalance == beforeBalance + (afterTotalDistributed - beforeTotalDistributed)
        //  - afterTotalDistributed >= beforeTotalDistributed
        //  - afterBlacklisted == true
        //  - contract's ETH increased by sendAmount
        // If call reverted then no observable changes to c's public state or balance should have occurred.
        assert(
            reverted
            ? (
                afterBalance == beforeBalance
                && afterTotalDistributed == beforeTotalDistributed
                && afterBlacklisted == beforeBlacklisted
                && contractEthAfter == contractEthBefore
              )
            : (
                afterTotalDistributed >= beforeTotalDistributed
                && afterBalance == beforeBalance + (afterTotalDistributed - beforeTotalDistributed)
                && afterBlacklisted == true
                && contractEthAfter == contractEthBefore + sendAmount
              )
        );
    }

    // allow receiving ETH so tests can fund this contract
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // run drives getTokens with an Ether value amount; we check a global invariant relating totalSupply, totalDistributed, and totalRemaining
    function run(uint256 sendAmount) public payable {
        require(address(this).balance >= sendAmount);

        // Read totals before the call
        uint256 beforeTotalSupply = c.totalSupply();
        uint256 beforeTotalDistributed = c.totalDistributed();
        uint256 beforeTotalRemaining = c.totalRemaining();

        bool reverted;
        // Call getTokens with provided Ether amount; capture revert status
        try c.getTokens{value: sendAmount}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read totals after the call
        uint256 afterTotalSupply = c.totalSupply();
        uint256 afterTotalDistributed = c.totalDistributed();
        uint256 afterTotalRemaining = c.totalRemaining();

        // General rule: regardless of sendAmount, after the call the invariant totalSupply == totalDistributed + totalRemaining must hold
        // If call reverted, state should be unchanged for these public vars (conservative): after == before
        if (reverted) {
            assert(afterTotalSupply == beforeTotalSupply && afterTotalDistributed == beforeTotalDistributed && afterTotalRemaining == beforeTotalRemaining);
        } else {
            assert(afterTotalSupply == (afterTotalDistributed + afterTotalRemaining));
        }
    }

    // Allow contract to receive Ether so it can forward to c
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Call getTokens with a provided Ether amount and check the invariant or unchanged state
    function run(uint256 sendAmount) public payable {
        require(address(this).balance >= sendAmount);

        // read before-values
        uint256 beforeTotalSupply = c.totalSupply();
        uint256 beforeTotalDistributed = c.totalDistributed();
        uint256 beforeTotalRemaining = c.totalRemaining();

        bool reverted;
        // perform the state-changing call as a top-level statement
        try c.getTokens{value: sendAmount}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        // read after-values
        uint256 afterTotalSupply = c.totalSupply();
        uint256 afterTotalDistributed = c.totalDistributed();
        uint256 afterTotalRemaining = c.totalRemaining();

        // Single general assertion: either reverted and all three public totals unchanged, or succeeded and invariant holds
        assert( (reverted && afterTotalSupply == beforeTotalSupply && afterTotalDistributed == beforeTotalDistributed && afterTotalRemaining == beforeTotalRemaining)
