    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Try a transfer from this contract (msg.sender == address(this)) to some recipient.
    // We check that when transfer succeeds, totalDistributed is unchanged and balances update accordingly;
    // when it reverts, nothing observable about totals changes.
    function run(address to, uint256 amount) public payable {
        require(to != address(0)); // avoid obvious zero-address which transfer disallows

        // read observable before-values
        uint256 beforeTotalDistributed = c.totalDistributed();
        uint256 beforeBalanceSender = c.balanceOf(address(this));
        uint256 beforeBalanceTo = c.balanceOf(to);

        bool reverted;
        try c.transfer(to, amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 afterTotalDistributed = c.totalDistributed();
        uint256 afterBalanceSender = c.balanceOf(address(this));
        uint256 afterBalanceTo = c.balanceOf(to);

        // General rule:
        // - totalDistributed must never change as a result of transfer calls
        // - if the call succeeded, sender balance decreased by amount and recipient increased by amount
        // - if the call reverted, balances and totals remain unchanged
        assert(
            afterTotalDistributed == beforeTotalDistributed
            && (
                // either reverted: balances unchanged
                (reverted && afterBalanceSender == beforeBalanceSender && afterBalanceTo == beforeBalanceTo)
                // or succeeded: balances moved by amount (but only if beforeBalanceSender had enough)
                || (!reverted && beforeBalanceSender >= amount && afterBalanceSender + amount == beforeBalanceSender && afterBalanceTo == beforeBalanceTo + amount)
            )
        );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We test transferFrom behavior from this contract as spender.
    // Preconditions: _from and _to non-zero, _from has at least _amount, and allowance for this contract >= _amount.
    function run(address _from, address _to, uint256 _amount) public payable {
        require(_from != address(0) && _to != address(0));

        // read before-values
        uint256 beforeTotalDistributed = c.totalDistributed();
        uint256 beforeFrom = c.balanceOf(_from);
        uint256 beforeTo = c.balanceOf(_to);
        uint256 beforeAllowance = c.allowance(_from, address(this));

        // require preconditions so that transferFrom is expected to succeed (if contract logic allows)
        require(beforeFrom >= _amount);
        require(beforeAllowance >= _amount);

        bool reverted;
        try c.transferFrom(_from, _to, _amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 afterTotalDistributed = c.totalDistributed();
        uint256 afterFrom = c.balanceOf(_from);
        uint256 afterTo = c.balanceOf(_to);

        // If succeeded: balances moved exactly _amount and totalDistributed unchanged.
        // If reverted: balances and totalDistributed unchanged.
        assert(
            (
                !reverted
                && afterFrom + _amount == beforeFrom
                && afterTo == beforeTo + _amount
                && afterTotalDistributed == beforeTotalDistributed
            )
            || (
                reverted
                && afterFrom == beforeFrom
                && afterTo == beforeTo
                && afterTotalDistributed == beforeTotalDistributed
            )
        );
    }

    receive() external payable {}
}
